def max_repeated_char(input_string):
    char_count = dict()
    for char in input_string:
        if char not in char_count:
            char_count[char] = 1
        else:
            char_count[char] += 1

    max_count = 0
    max_char = None
    for char, count in char_count.items():
        if count > max_count:
            max_count = count
            max_char = char

    return max_char

# Example usage:
input_str = "examplestring"
print(max_repeated_char(input_str))  # Output: 'e' assuming 'e' is the most frequent character
```

